<section class="housing-gallery" x-data="housingGallery(@js($images))" aria-label="Bộ ảnh {{ $title }}">
<div class="housing-main-photo"><button type="button" class="h-full w-full" @click="$refs.viewer.showModal()" aria-label="Phóng to ảnh"><img :src="images[active]" src="{{ $images[0] }}" alt="{{ $title }}" referrerpolicy="no-referrer" x-on:error="imageError($event)"></button>
@if(count($images)>1)<button class="housing-arrow housing-arrow-prev" type="button" @click="move(-1)" aria-label="Ảnh trước">‹</button><button class="housing-arrow housing-arrow-next" type="button" @click="move(1)" aria-label="Ảnh tiếp theo">›</button>@endif
<span class="housing-photo-count" x-text="(active + 1) + ' / ' + images.length"></span></div>
<div class="housing-thumbnails">@foreach($images as $i=>$url)<button type="button" @click="active = {{ $i }}" :aria-pressed="active === {{ $i }}" :class="{'is-active': active === {{ $i }}}" aria-label="Xem ảnh {{ $i+1 }}"><img src="{{ $url }}" alt="Ảnh {{ $i+1 }}" loading="lazy" referrerpolicy="no-referrer" x-on:error="imageError($event)"></button>@endforeach</div>
<dialog x-ref="viewer" class="housing-viewer" @click="if ($event.target === $el) $el.close()" @keydown.right.prevent="move(1)" @keydown.left.prevent="move(-1)"><div><button type="button" class="app-button-muted" @click="$refs.viewer.close()" autofocus>Đóng ảnh ×</button><img :src="images[active]" alt="{{ $title }}" referrerpolicy="no-referrer" x-on:error="imageError($event)"><div class="flex items-center justify-center gap-4"><button type="button" class="app-button-muted" @click="move(-1)">← Ảnh trước</button><span x-text="(active + 1) + ' / ' + images.length"></span><button type="button" class="app-button-muted" @click="move(1)">Ảnh sau →</button></div></div></dialog>
</section>
